import type { DocumentLoader } from "./docloader.ts";

/**
 * An object of a vocabulary class generated by `@fedify/vocab-tools`, such
 * as `Note` or `Person` from `@fedify/vocab`.
 *
 * Every root class that `@fedify/vocab-tools` generates implements this
 * interface, so it covers the classes of third-party vocabulary modules
 * generated with the same tool as well.  Only generated classes are meant to
 * implement it: the `"~fedify.vocab"` brand keeps arbitrary objects with a
 * `toJsonLd()` method from satisfying it by accident.
 *
 * @since 2.5.0
 */
export interface VocabularyObject {
  /**
   * The brand that marks generated vocabulary objects.  It is always `true`.
   * Its name is a string rather than a symbol, so that objects generated
   * against different copies of `@fedify/vocab-runtime` stay compatible with
   * each other's type declarations.
   */
  readonly "~fedify.vocab": true;

  /**
   * The object's `@id`, or `null` if it has none.
   */
  readonly id: URL | null;

  /**
   * Converts this object to a JSON-LD structure.
   * @param options The options to use.
   * @returns The JSON-LD representation of this object.
   */
  toJsonLd(options?: {
    format?: "compact" | "expand";
    contextLoader?: DocumentLoader;
    context?:
      | string
      | Record<string, string>
      | (string | Record<string, string>)[];
  }): Promise<unknown>;
}

/**
 * A value object in expanded JSON-LD, such as
 * `{ "@value": "Hello", "@language": "en" }`.  A JSON literal has
 * `"@type": "@json"`, and its `@value` is the JSON value itself.
 * @since 2.5.0
 */
export interface RawValueObject {
  readonly "@value": unknown;
  readonly "@type"?: string;
  readonly "@language"?: string;
  readonly "@direction"?: "ltr" | "rtl";
  readonly "@index"?: string;
}

/**
 * A node object in expanded JSON-LD: a reference such as
 * `{ "@id": "https://example.com/" }`, or an embedded node whose other keys
 * are full property IRIs with arrays of {@link RawPropertyValue}s.
 * A graph object, which has a `@graph` key, also takes this shape.
 * @since 2.5.0
 */
export interface RawNodeObject {
  readonly "@id"?: string;
  readonly "@type"?: readonly string[];
  readonly [key: string]: unknown;
}

/**
 * A list object in expanded JSON-LD, used for properties whose values are
 * ordered, such as `{ "@list": [{ "@value": 1 }, { "@value": 2 }] }`.
 * @since 2.5.0
 */
export interface RawListObject {
  readonly "@list": readonly RawPropertyValue[];
  readonly "@index"?: string;
}

/**
 * A single value of a property in expanded JSON-LD, as returned by the
 * `getRawPropertyValues()` function generated by `@fedify/vocab-tools`.
 * Narrow it with the `in` operator, e.g., `"@value" in value`.
 * @since 2.5.0
 */
export type RawPropertyValue = RawValueObject | RawNodeObject | RawListObject;
